#include <iostream>
#include <memory>

struct Node {
    char data;
    Node* next{nullptr};
};

bool isEmpty(const Node* head) {
    return head == nullptr;
}

void insertOrdered(Node*& head, char value) {
    Node* newNode = new Node{value, nullptr};
    Node* previousPtr = nullptr;
    Node* currentPtr = head;

    while (currentPtr != nullptr && value > currentPtr->data) {
        previousPtr = currentPtr;
        currentPtr = currentPtr->next;
    }

    if (previousPtr == nullptr) {
        newNode->next = head;
        head = newNode;
    } else {
        previousPtr->next = newNode;
        newNode->next = currentPtr;
    }
}

void printList(const Node* currentPtr) {
    if (isEmpty(currentPtr)) {
        std::cout << "List is empty.\n";
        return;
    }
    std::cout << "The list is: ";
    while (currentPtr != nullptr) {
        std::cout << currentPtr->data << " --> ";
        currentPtr = currentPtr->next;
    }
    std::cout << "nullptr\n";
}

void freeList(Node*& head) {
    while (head != nullptr) {
        Node* temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    Node* listHead = nullptr;
    insertOrdered(listHead, 'B');
    insertOrdered(listHead, 'A');
    insertOrdered(listHead, 'C');
    printList(listHead);
    freeList(listHead);
    return 0;
}

#include <iostream>
#include <optional>

struct Node {
    char data;
    Node* next{nullptr};
};

void insertOrdered(Node*& head, char value) {
    Node* newNode = new Node{value, nullptr};
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr && value > curr->data) {
        prev = curr;
        curr = curr->next;
    }
    if (prev == nullptr) {
        newNode->next = head;
        head = newNode;
    } else {
        prev->next = newNode;
        newNode->next = curr;
    }
}

std::optional<char> deleteNode(Node*& head, char value) {
    if (head == nullptr) return std::nullopt;

    if (head->data == value) {
        Node* temp = head;
        head = head->next;
        char deletedVal = temp->data;
        delete temp;
        return deletedVal;
    }

    Node* prev = head;
    Node* curr = head->next;
    while (curr != nullptr && curr->data != value) {
        prev = curr;
        curr = curr->next;
    }

    if (curr != nullptr) {
        Node* temp = curr;
        prev->next = curr->next;
        char deletedVal = temp->data;
        delete temp;
        return deletedVal;
    }

    return std::nullopt;
}

void printList(const Node* curr) {
    if (curr == nullptr) {
        std::cout << "List is empty.\n";
        return;
    }
    while (curr != nullptr) {
        std::cout << curr->data << " --> ";
        curr = curr->next;
    }
    std::cout << "NULL\n";
}

int main() {
    Node* head = nullptr;
    insertOrdered(head, 'A');
    insertOrdered(head, 'B');
    insertOrdered(head, 'C');

    printList(head);
    auto res1 = deleteNode(head, 'B');
    if (res1) std::cout << *res1 << " deleted.\n";
    printList(head);

    auto res2 = deleteNode(head, 'Z');
    if (!res2) std::cout << "Z not found.\n";

    // Clean up remaining nodes
    while (head != nullptr) {
        Node* t = head;
        head = head->next;
        delete t;
    }
    return 0;
}
